const inp = $input.first().json;
const query = String(inp.query ?? "").trim();
if (!query) throw new Error("Input 'query' mangler.");

const numOrNull = (v) => {
  if (v === undefined || v === null || v === "") return null;
  const n = Number(String(v).replace(",", "."));
  return Number.isFinite(n) ? n : null;
};
// 0 betyder "ikke angivet" (modeller udfylder ofte 0 som standard)
const unit = (v) => {
  const n = numOrNull(v);
  return n === null || n <= 0 ? null : Math.min(1, n);
};

let limit = numOrNull(inp.limit);
limit = limit ? Math.min(10, Math.max(1, Math.round(limit))) : 5;

const genre = String(inp.genre ?? "").trim() || null;

const filters = {
  genre,
  min_energy: unit(inp.min_energy),
  max_energy: unit(inp.max_energy),
  min_danceability: unit(inp.min_danceability),
  max_danceability: unit(inp.max_danceability),
  min_valence: unit(inp.min_valence),
  max_valence: unit(inp.max_valence),
};

return [{ json: {
  query, limit, filters,
  embeddingBody: { model: "text-embedding-3-small", input: query }
}}];

const embedding = $json.data?.[0]?.embedding;
if (!Array.isArray(embedding) || embedding.length !== 1536) {
  throw new Error("Embedding mangler eller har forkert dimension.");
}
const { query, limit, filters } = $('Prepare input').first().json;
const hasFilter = Object.values(filters).some(v => v !== null);
const k = hasFilter ? 500 : limit;   // hent flere kandidater, hvis der skal filtreres bagefter

const statement = `
CALL db.index.vector.queryNodes('track_vibe_index', $k, $embedding)
YIELD node, score
WHERE ($genre IS NULL OR EXISTS {
        MATCH (node)-[:IN_GENRE]->(gg:Genre)
        WHERE toLower(gg.name) = toLower($genre) })
  AND ($minEnergy IS NULL OR node.energy >= $minEnergy)
  AND ($maxEnergy IS NULL OR node.energy <= $maxEnergy)
  AND ($minDance IS NULL OR node.danceability >= $minDance)
  AND ($maxDance IS NULL OR node.danceability <= $maxDance)
  AND ($minValence IS NULL OR node.valence >= $minValence)
  AND ($maxValence IS NULL OR node.valence <= $maxValence)
WITH node, score ORDER BY score DESC LIMIT $limit
OPTIONAL MATCH (node)-[:PERFORMED_BY]->(a:Artist)
OPTIONAL MATCH (node)-[:IN_GENRE]->(g:Genre)
OPTIONAL MATCH (node)-[:ON_ALBUM]->(al:Album)
RETURN node.track_id AS track_id,
       node.title AS title,
       a.name AS artist,
       g.name AS genre,
       al.name AS album,
       node.release_year AS release_year,
       node.energy AS energy,
       node.danceability AS danceability,
       node.valence AS valence,
       round(score * 1000) / 1000 AS similarity,
       [(node)-[:SIMILAR_TO]-(o:Track)-[:PERFORMED_BY]->(oa:Artist) | o.title + ' - ' + oa.name][..3] AS similar_via_graph
ORDER BY score DESC
`;

const parameters = {
  embedding, k, limit,
  genre: filters.genre,
  minEnergy: filters.min_energy, maxEnergy: filters.max_energy,
  minDance: filters.min_danceability, maxDance: filters.max_danceability,
  minValence: filters.min_valence, maxValence: filters.max_valence,
};

return [{ json: {
  neo4jBody: { statements: [{ statement, parameters }] },
  meta: { source: "Neo4j vector index track_vibe_index (semantisk søgning)",
          info: { query, filters_applied: filters } }
}}];

if ($json.errors?.length) {
  throw new Error("Neo4j fejl: " + JSON.stringify($json.errors));
}
const result = $json.results?.[0];
const columns = result?.columns ?? [];
const rows = (result?.data ?? []).map(item =>
  Object.fromEntries(columns.map((c, i) => [c, item.row[i]]))
);
const meta = $('Build query').first().json.meta;

return [{ json: {
  source: meta.source,
  ...meta.info,
  count: rows.length,
  results: rows,
  note: rows.length === 0
    ? "Ingen resultater i databasen. Fortæl brugeren det ærligt og foreslå en anden søgning."
    : "Brug kun disse resultater. Angiv track_id/kilde, når du citerer dem."
}}];
